-- CURRENTLY: places and moments. The words for the Currently field: every classic zone and
-- its most-visited subzones, the capitals' districts, battlegrounds, the seas, the hour in
-- each place, and the moments the game itself shows (a breath held underwater, a ghost on
-- its way back, a druid's shape, a queue, a duel, a barber's chair).
-- Loaded after Words.lua; it only adds to ns.Words. Every line is a whole phrase that reads
-- after a mood ("Weary, <phrase>."), says only what the game shows, and names no one.
local _, ns = ...
local W = ns.Words

local function extend(t, key, list)
  local cur = t[key]
  if type(cur) == "string" then cur = { cur } end
  cur = cur or {}
  for _, l in ipairs(list) do cur[#cur + 1] = l end
  t[key] = cur
end
local function extendAll(t, more) for k, list in pairs(more) do extend(t, k, list) end end

